import net.neoforged.neoforge.common.MutableDataComponentHolder;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.network.chat.Component;

// Create custom data component type (in data generation)
DataComponentType<Component> CUSTOM_NAME = DataComponentType.<Component>builder()
    .persistent(Component.CODEC)
    .build();

// Use on item stack
itemStack.set(CUSTOM_NAME, Component.literal("My Sword"));
Component name = itemStack.get(CUSTOM_NAME).orElse(null);
